import{z as B,x as u,o as e,c as A,q as i,j as t,D as n,d as r,s as E,S as s,b as o}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"Voronoi 与 Delaunay","description":"","frontmatter":{"title":"Voronoi 与 Delaunay","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/voronoi-delaunay.md","filePath":"cs/voronoi-delaunay.md","lastUpdated":1791063341000}'),d={name:"cs/voronoi-delaunay.md"};function p(D,a,h,m,f,y){const l=u("Mermaid");return e(),A("div",null,[a[2]||(a[2]=i('<h1 id="voronoi-与-delaunay" tabindex="-1">Voronoi 与 Delaunay <a class="header-anchor" href="#voronoi-与-delaunay" aria-label="Permalink to &quot;Voronoi 与 Delaunay&quot;">​</a></h1><div class="epigraph"><p>Voronoi 胞是距站点最近的区域；对偶是 Delaunay 三角剖分：空圆，最大化最小角。</p><footer>—— 据 Fortune, A Sweepline Algorithm for Voronoi Diagrams, 1987；Delaunay, 1934；CLRS 第 33 章整理</footer></div><p>上一课<a href="/cs/half-plane-intersection">半平面交</a>给了凸可行域：对每个站点 \\(p_i\\)，它的 Voronoi 胞 \\(\\{x:\\|x-p_i\\|\\le\\|x-p_j\\|\\}\\) 正是若干半平面的交。但逐点求胞等于把半平面交跑 \\(n\\) 遍，整体结构仍看不见。缺口是整体图：Voronoi 图与其对偶 Delaunay 三角剖分，Fortune 扫描线 \\(O(n\\log n)\\) 一遍全出。本课不重写单个半平面交；后课点定位就建立在这些剖分上。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Delaunay 的定义：三角形的外接圆内不含任何其他站点（一般位置下剖分唯一）。对偶关系：两胞在 Voronoi 图共享一条边 \\(\\Leftrightarrow\\) 两站点在 Delaunay 有一条边。这条对偶白送一批性质：Delaunay 最大化最小角——最「胖」的剖分，数值上最稳；任一点的最近邻必与它有 Delaunay 边；欧氏 MST 是 Delaunay 的子图。三种几何问题共用一张图。</p><p>缺口是对偶结构本身，不是再跑 \\(n\\) 次半平面交。</p><p><span class="marginnote">「空圆性质」翻译成大白话：任何 Delaunay 三角形的外接圆里都不许挤进别的站点——正是这条约束把又扁又瘦的三角形排除在外，留下最大化最小角的「胖」剖分。初学者容易以为 Voronoi 边一定穿过两站点连线的中点，实际上它只是垂直平分线上的一段，中点未必落在画出的那条边上。</span></p><h3 id="不是-k-nn-机器学习课" tabindex="-1">不是 k-NN 机器学习课 <a class="header-anchor" href="#不是-k-nn-机器学习课" aria-label="Permalink to &quot;不是 k-NN 机器学习课&quot;">​</a></h3><p>本课是几何最近邻图，不是 k-NN 机器学习课。高维里 Voronoi 胞的组合数指数爆炸，本课只谈平面。</p><p><span class="marginnote">Fortune 1987 海滩线。Delaunay 1934。后课点定位：Kirkpatrick 或梯形图。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>两条路。Fortune 扫描线从左到右扫过站点，扫描线前方是海滩线——各站点抛物线的下包络，断点的轨迹恰是 Voronoi 边；事件只有站点事件与圆事件（生成顶点）两类、总量线性，配堆即 \\(O(n\\log n)\\)。实现更省心的是 Lawson 增量：从任意三角剖分起步，逐点插入并翻转不满足空圆性的边，直到全局合法。输出边表。</p>',12)),(e(),t(s,null,{default:n(()=>[E(l,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E7%AB%99%E7%82%B9%22%5D%20--%3E%20VOR%5B%22Voronoi%20%E8%83%9E%22%5D%0A%20%20VOR%20--%3E%20DEL%5B%22Delaunay%20%E5%AF%B9%E5%81%B6%22%5D%0A%20%20DEL%20--%3E%20MST%5B%22%E5%90%AB%E6%AC%A7%E6%B0%8F%20MST%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o("p",null,[o("span",{class:"marginnote"},"代入数字看结构量级：一般位置下 \\(n\\) 个点、凸包 \\(h\\) 个顶点，Delaunay 剖分恰有 \\(2n-2-h\\) 个三角形、不超过 \\(3n-3-h\\) 条边——都是线性规模。正因为结构是线性的，\\(O(n\\log n)\\) 的算法才「装得下」它；这也是它比全配对图（\\(n(n-1)/2\\) 条边）实用的原因。")],-1)),a[4]||(a[4]=o("p",null,"假设一般位置：无四点共圆；退化情形按共圆链处理。",-1)),a[5]||(a[5]=o("h2",{id:"机制",tabindex:"-1"},[r("机制 "),o("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=o("p",null,"机制核心是「空圆 \\(\\Leftrightarrow\\) 对偶边」：两站点存在一条内部无点的公共空圆 \\(\\Leftrightarrow\\) 它们的胞相邻。海滩线随扫描移动，断点扫出的轨迹恰是 Voronoi 边——这就是 Fortune 只需线性个事件的道理。与其他几何对象挂钩：Delaunay 最外层的边连成凸包，最近点对的那条边必在 Delaunay 里——先剖分，一批查询问题一次解决。",-1)),(e(),t(s,null,{default:n(()=>[E(l,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20INS%5B%22%E6%8F%92%E5%85%A5%E6%96%B0%E7%AB%99%E7%82%B9%22%5D%20--%3E%20LOC%5B%22%E5%AE%9A%E4%BD%8D%E5%AE%83%E8%90%BD%E5%9C%A8%E5%93%AA%E4%B8%AA%E4%B8%89%E8%A7%92%E5%BD%A2%22%5D%0A%20%20LOC%20--%3E%20CON%5B%22%E4%B8%8E%E8%AF%A5%E4%B8%89%E8%A7%92%E5%BD%A2%E4%B8%89%E4%B8%AA%E9%A1%B6%E7%82%B9%E8%BF%9E%E8%BE%B9%22%5D%0A%20%20CON%20--%3E%20CHK%7B%22%E7%9B%B8%E9%82%BB%E4%B8%89%E8%A7%92%E5%BD%A2%E6%98%AF%E5%90%A6%E6%BB%A1%E8%B6%B3%E7%A9%BA%E5%9C%86%3F%22%7D%0A%20%20CHK%20--%20%E5%90%A6%20--%3E%20FLIP%5B%22%E7%BF%BB%E8%BD%AC%E8%AF%A5%E8%BE%B9%22%5D%0A%20%20FLIP%20--%3E%20CHK%0A%20%20CHK%20--%20%E5%85%A8%E9%83%A8%E9%80%9A%E8%BF%87%20--%3E%20OUT%5B%22%E6%9B%B4%E6%96%B0%E8%BE%B9%E8%A1%A8%2C%20%E8%BE%93%E5%87%BA%20Delaunay%22%5D%0A"})]),fallback:n(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=i('<p><span class="marginnote">海滩线可以想象成多块石头同时落进池塘：把扫描线当作「水面」，每块石头激起的圆波纹彼此相遇，相遇点的轨迹描出一条线——那条线正是 Voronoi 边的雏形。石头（站点）每多激起或消失一圈，就对应一个站点事件或圆事件。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写高阶 Voronoi（k 阶近邻），加权距离的功率图点名即可。后课默认：平面 Voronoi/Delaunay \\(O(n\\log n)\\)。下一课点定位。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Voronoi 最近区域；Delaunay 空圆三角。</li><li>对偶；含 MST 与最近邻边。</li><li>Fortune 扫描 \\(O(n\\log n)\\)。</li><li>出处：Fortune, 1987；Delaunay, 1934。</li></ul>',5))])}const _=B(d,[["render",p]]);export{c as __pageData,_ as default};
